import { normaliseText } from '../helpers/text.js';

/** The title as librarians file it: without a leading 'The', 'A' or 'An' (a title that is only an article is kept). */
function filingTitle(title) {
  return title.trim().replace(/^(?:the|an|a)\s+(?=\S)/i, '');
}

/** Returns the items whose title or author holds every word of the query, sorted by filing title (ignoring a leading 'The', 'A' or 'An'). */
export function searchCatalog(items, query) {
  const words = normaliseText(query).split(' ').filter(Boolean);
  if (words.length === 0) return [];
  return items
    .filter((item) => {
      const searchable = normaliseText(`${item.title} ${item.author}`);
      return words.every((word) => searchable.includes(word));
    })
    .sort(
      (first, second) =>
        filingTitle(first.title).localeCompare(filingTitle(second.title)) ||
        first.title.localeCompare(second.title),
    );
}

